//! 🧪️ A source-closure fold lends all six complete causes under one original caller before full paid retirement.
use semio_framework_job::{OriginalClosureFailure,OriginalTurnFailure,OriginalDomainProjection,OriginalDomainView as V,OriginalJobFixtureCaller,OperationId,Generation,admit_original_domain_failure,original_domain_failure_demand,close_original_retained_step};
use semio_framework_value::{ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,retirement::controlled::ControlledRetirement};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn clock()->Option<u64>{Some(1000)}
fn turn(primary:ValueRefusalKind,message:&'static str,receipt:&'static str,context:&'static str,receipt_kind:ValueRefusalKind,context_kind:ValueRefusalKind)->OriginalTurnFailure{{let original=OriginalTurnFailure::from(ValueError::literal(primary,message));OriginalTurnFailure{receipt_refusal:Some(ValueError::literal(receipt_kind,receipt)),context_refusal:Some(ValueError::literal(context_kind,context)),..original}}}
#[test]
fn original_source_closure_full_pair_same_caller_denials_and_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../../🛍️products/💻️os/🔨️modules/🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 for copy in [1,3,64]{let(mut caller,bootstrap)=observe(||OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()));let mut born=bootstrap.requested_bytes;let mut freed=bootstrap.released_bytes;
  caller.turn(stock,|cx|{let mut source=Some(OriginalClosureFailure{initial:turn(ValueRefusalKind::InvalidValue,"initial original semantic","initial original receipt","initial original context",ValueRefusalKind::InvariantViolated,ValueRefusalKind::WorkLimit),closure:turn(ValueRefusalKind::OwnershipLimit,"closure original semantic","closure original receipt","closure original context",ValueRefusalKind::AllocationFailed,ValueRefusalKind::DepthLimit)});let pointer=source.as_ref().unwrap().initial.primary.message().as_ptr();let demand=original_domain_failure_demand::<OriginalClosureFailure>();let identity=(cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity());for denied in [RetainedCloneGrant{maximum_items:0,..cx.retained_grant()},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..cx.retained_grant()},RetainedCloneGrant{maximum_depth:0,..cx.retained_grant()}]{let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observe(||cx.with_retained_loan(denied,|same|Ok(admit_original_domain_failure(&mut source,same)?.is_none())));assert!(result?);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert_eq!(source.as_ref().unwrap().initial.primary.message().as_ptr(),pointer)}
   let(result,heap)=observe(||admit_original_domain_failure(&mut source,cx));let failure=result?.unwrap();assert!(source.is_none());assert_eq!(heap.requested_bytes,demand.capacity_bytes);born+=heap.requested_bytes;freed+=heap.released_bytes;let projection=failure.primary_domain().unwrap().projection();assert_eq!(failure.primary.message().as_ptr(),pointer);assert_eq!(failure.primary.retained_progress(),RetainedCloneProgress::default());assert_eq!(projection.projection_key(&[],0)?,"initial");assert_eq!(projection.projection_key(&[],1)?,"closure");for (index,key) in ["initial","closure"].iter().enumerate(){for (ordinal,field) in ["primary","receiptRefusal","contextRefusal"].iter().enumerate(){let prefix=if ordinal==0{[index,0,1,0]}else{[index,ordinal,0,usize::MAX]};let path=if ordinal==0{&prefix[..]}else{&prefix[..3]};assert!(matches!(projection.projection_view(path)?,V::IntrinsicText(kind)if kind==law["wire"][*key][*field]["kind"].as_str().unwrap()));let message=if ordinal==0{[index,0,1,1]}else{[index,ordinal,1,usize::MAX]};let path=if ordinal==0{&message[..]}else{&message[..3]};assert!(matches!(projection.projection_view(path)?,V::IntrinsicText(text)if text==law["wire"][*key][*field]["message"].as_str().unwrap()))}}assert!(matches!(projection.projection_view(&[0,0,1,1])?,V::IntrinsicText(message)if message.as_ptr()==pointer));assert!(matches!(projection.projection_view(&[1,2,1])?,V::IntrinsicText(message)if message=="closure original context"));assert_eq!((cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity()),identity);
   let progress=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant()).unwrap();cx.consume_retained(progress)?;cx.consume_fuel(1);let mut owner=ControlledRetirement::new(failure).unwrap_or_else(|_|unreachable!());for _ in 0..100000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()};let(result,heap)=observe(||cx.with_retained_loan(grant,|same|close_original_retained_step(same,owner.selected_demand(grant.maximum_copy_bytes)?,|grant|owner.step(grant))));let progress=result?.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes}assert!(owner.terminal_is_empty());let(_,heap)=observe(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();let(_,heap)=observe(||caller.retire(stock));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(born,freed);}
}
